UPSTREAM_SHA='741ca9f7d72923f7b13c1c2462ca90eba81e1a87'
def _ms(a,b):return None if a is None or b is None else (b-a)/1_000_000
def _duration_values(rows,a,b):return [v for r in rows if (v:=_ms(r.get(a),r.get(b))) is not None]
def _pct(values,p):return percentile(values,p) if values else None
def build_report(store:Store,run_id:str)->dict:
    rows=store.shadow_rows(run_id);meta=store.get_run_metadata(run_id) or {};fills=store.all_fills(run_id);deposits=store.all_deposits(run_id);gaps=store.unresolved_decode_gaps(run_id);counters=store.counters(run_id);canonical_counters=store.canonical_counters(run_id)
    t01=_duration_values(rows,'t0_monotonic_ns','t1_monotonic_ns');tat1=_duration_values(rows,'ta_monotonic_ns','t1_monotonic_ns');t12=_duration_values(rows,'t1_monotonic_ns','t2_monotonic_ns');t23=_duration_values(rows,'t2_monotonic_ns','t3_monotonic_ns');t03=_duration_values(rows,'t0_monotonic_ns','t3_monotonic_ns');tat3=_duration_values(rows,'ta_monotonic_ns','t3_monotonic_ns')
    actionable=[r for r in rows if r.get('ta_monotonic_ns') is not None and r.get('live_equivalent_confirmations_satisfied') is True];headrooms=[r['shadow_headroom_ms'] for r in actionable if r.get('shadow_headroom_ms') is not None and r.get('winner_fill_type') in COMPETITIVE_FILL_TYPES];winner_lat=[r['winner_latency_ms'] for r in actionable if r.get('winner_latency_ms') is not None and r.get('winner_fill_type') in COMPETITIVE_FILL_TYPES];ready=[r for r in actionable if r.get('transaction_ready') is True and r.get('shadow_headroom_ms') is not None and r.get('winner_fill_type') in COMPETITIVE_FILL_TYPES];rb=sum(1 for r in ready if r['shadow_headroom_ms']>0);ft=fill_type_counts(fills);unknown_ft=sum(v for k,v in ft.items() if k.startswith('UNKNOWN_'))
    rep={'run_id':run_id,'schema_version':4,'patch_sha256':meta.get('patch_sha256','UNKNOWN'),'upstream_sha':meta.get('upstream_sha',UPSTREAM_SHA),'our_sha':meta.get('our_sha','UNKNOWN'),'start_utc':meta.get('start_utc','UNKNOWN'),'end_utc':meta.get('end_utc','UNKNOWN'),'runtime_monotonic_ns':meta.get('runtime_monotonic_ns'),'runtime_hours':(meta.get('runtime_monotonic_ns')/3_600_000_000_000 if meta.get('runtime_monotonic_ns') is not None else None),'config_fingerprint_sha256':meta.get('config_fingerprint_sha256','UNKNOWN'),'routes':meta.get('routes',[]),'endpoint_classes':meta.get('endpoint_classes',[]),'deposits_observed':len(deposits),'raw_candidates':len(rows),'live_equivalent_actionable_candidates':len(actionable),'simulation_early_not_live_actionable':sum(bool(r.get('simulation_early_not_live_actionable')) for r in rows),'open_opportunities':sum(r.get('candidate_type')=='open' for r in actionable),'step_in_opportunities':sum(r.get('candidate_type')=='step_in' for r in actionable),'exclusive_other':sum(r.get('candidate_type')=='exclusive_other' for r in actionable),'eligible_opportunities':sum(r.get('eligible') is True for r in actionable),'profitable_candidates':sum(r.get('profitability_decision')=='profitable' for r in actionable),'profitable_if_won_observations':sum(bool(r.get('profitability_decision')=='profitable' and r.get('winner_tx_hash')) for r in actionable),'tx_ready_candidates':sum(r.get('transaction_ready') is True for r in actionable),'t0_t1_p50_ms':_pct(t01,.5),'ta_t1_p50_ms':_pct(tat1,.5),'ta_t1_p90_ms':_pct(tat1,.9),'t1_t2_p50_ms':_pct(t12,.5),'t1_t2_p90_ms':_pct(t12,.9),'t2_t3_p50_ms':_pct(t23,.5),'t2_t3_p90_ms':_pct(t23,.9),'t0_t3_p50_ms':_pct(t03,.5),'ta_t3_p50_ms':_pct(tat3,.5),'ta_t3_p90_ms':_pct(tat3,.9),'winner_latency_p50_ms':_pct(winner_lat,.5),'winner_latency_p90_ms':_pct(winner_lat,.9),'ready_before_winner_count':rb,'ready_before_winner_denominator':len(ready),'ready_before_winner_pct':100*rb/len(ready) if ready else None,'headroom_p10_ms':_pct(headrooms,.1),'headroom_p50_ms':_pct(headrooms,.5),'headroom_p90_ms':_pct(headrooms,.9),'fill_type_counts':ft,'competitive_fill_types':['FastFill','ReplacedSlowFill'],'slow_fill_count':ft.get('SlowFill',0),'unknown_fill_type_count':unknown_ft,'fast_fills_observed':ft.get('FastFill',0),'replaced_slow_fills_observed':ft.get('ReplacedSlowFill',0),'slow_fills_observed':ft.get('SlowFill',0),'unresolved_decode_count':len(gaps),'unresolved_decode_events':len(gaps),'unresolved_decode_blocks':sorted({g['block_number'] for g in gaps}),'competitiveness_metrics_complete':len(gaps)==0 and unknown_ft==0,'economics':summarize_economics(rows),'timeboost_relevance':meta.get('timeboost_relevance','UNKNOWN'),'sequencer_feed_lead_p50_ms':meta.get('sequencer_feed_lead_p50_ms'),'sequencer_feed_verdict':meta.get('sequencer_feed','UNKNOWN'),'rpc_latency_verdict':meta.get('rpc_latency','UNKNOWN'),'zero_live_tx_proof':meta.get('zero_write_rpc_proof','UNKNOWN'),'secret_scan':meta.get('secret_scan','UNKNOWN'),'tests':meta.get('tests','UNKNOWN'),'live_execution_lock':meta.get('live_execution_lock','PASS_STATIC / EXECUTION_NOT_TESTED'),'zero_spend_proof':meta.get('zero_spend_proof','PASS'),'real_network_benchmark':meta.get('real_network_benchmark','UNKNOWN'),'data_completeness':'COMPLETE' if len(gaps)==0 and unknown_ft==0 else 'INCOMPLETE','known_unknowns':meta.get('known_unknowns',['REBALANCE_COST','REAL_NETWORK_SAMPLE','UPSTREAM_PATCH_EXECUTION']),'observer_counters':{'operational':counters,'canonical':canonical_counters},'warning':'READY_BEFORE_WINNER_IS_NOT_EQUIVALENT_TO_WOULD_HAVE_WON; BUSINESS_TIMING_USES_TA_NOT_RAW_T0','competitors':competitor_scoreboard(deposits,fills,competitive_only=True)}
    rep.update({'median_t0_t1_ms':median(t01) if t01 else None,'median_ta_t1_ms':median(tat1) if tat1 else None,'median_t1_t2_ms':median(t12) if t12 else None,'median_t2_t3_ms':median(t23) if t23 else None,'median_ta_t3_ms':median(tat3) if tat3 else None,'median_shadow_headroom_ms':median(headrooms) if headrooms else None,'attempt_integrity':{'attempt_count':sum(bool(r.get('evaluation_attempt_id')) for r in rows),'deposit_versions':len({r.get('deposit_version_id') for r in rows if r.get('deposit_version_id')})}});return rep
def export_artifacts(store:Store,run_id:str,out_dir:str|Path)->dict:
    out=Path(out_dir);out.mkdir(parents=True,exist_ok=True);rows=store.shadow_rows(run_id);report=build_report(store,run_id);(out/'run-metadata.json').write_text(json.dumps(report,indent=2,sort_keys=True)+'\n');(out/'shadow-records.jsonl').write_text(''.join(json.dumps(r,sort_keys=True)+'\n' for r in rows))
    with (out/'competitors.csv').open('w',newline='') as f:
        fields=['relayer','fills_observed','median_deposit_to_fill_ms','p10_ms','p90_ms','routes','fill_types'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader();
        for row in report['competitors']:row=dict(row);row['routes']='|'.join(row['routes']);row['fill_types']=json.dumps(row['fill_types'],sort_keys=True);w.writerow(row)
    with (out/'latency.csv').open('w',newline='') as f:
        fields=['deposit_key','trace_id','evaluation_attempt_id','deposit_version_id','ta_monotonic_ns','winner_fill_type','winner_latency_ms','shadow_headroom_ms'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader();
        for r in rows:w.writerow({k:r.get(k) for k in fields})
    (out/'observer-counters.json').write_text(json.dumps(report['observer_counters'],indent=2,sort_keys=True)+'\n');(out/'decode-gaps.json').write_text(json.dumps(store.unresolved_decode_gaps(run_id),indent=2,sort_keys=True)+'\n');return report
